(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["uk"] = {"ui":{"skip":"Перейти до вмісту","back":"← Назад до AI-gile","lang.button":"Мова: {name}","lang.dialog":"Обери мову","lang.search":"Шукати мову","lang.none":"Жодна мова не підходить","lang.notYet":"{name} ще не перекладено","theme.aria":"Змінити тему: світла, темна чи чорна","theme.toLight":"Перемкнути на світлу тему","theme.toDark":"Перемкнути на темну тему","theme.toBlack":"Перемкнути на чорну тему (справжній чорний, добре для екранів OLED)","words.underline":"Підкреслити ці слова на сторінці","words.underlineHelp":"Наведи курсор або торкнися слова з крапковим підкресленням, щоб побачити, що воно означає.","index.title":"AI-gile: твоя ШІ-команда розробників на одній дошці","index.description":"AI-gile — це канбан-дошка для команд, що пишуть код разом зі ШІ. Вони працюють, поки ти спиш, а тобі лишається одна коротка купка: що вирішити, що перевірити і що прийняти.","hero.logoAlt":"Значок дошки AI-gile","hero.h1.html":"Твоя ШІ-команда розробників на одній&nbsp;дошці.","hero.alpha":"🐣 Закрита пре-альфа","hero.alphaTitle":"Рано й недороблено: дякуємо, що пробуєш!","hero.lede":"Вони працюють, поки ти спиш. Зранку на тебе чекає коротка купка: кілька запитань, кілька речей на перевірку, один-два фіолетові діаманти. Клацни, прийми й повертайся до кави.","dl.windows":"Застосунок для Windows","dl.browser":"Запустити в браузері","dl.messenger":"📱 Messenger для телефона","dl.soon":"Скоро","dl.notify":"🔔 Сповісти, коли відкриється","dl.notifySmall":"Альфа або бета","hero.secondary":"Agile, але команді ніколи не потрібна кава на стендапі. (Стендапи вони все одно проводять.)","pitch.h2":"AI-gile стількома словами, скількома захочеш","pitch.lede":"Обери довжину: від одного слова до 144. Кожна довжина — окремий опис, написаний саме під цей розмір. Тягни повзунок або користуйся стрілками.","pitch.rangeLabel":"Довжина в словах","pitch.dice":"🎲 інший варіант","pitch.words.one":"{n} слово","pitch.words.other":"{n} слова","pitch.letters.one":"{n} літера","pitch.letters.other":"{n} літери","pitch.chars.one":"{n} символ","pitch.chars.other":"{n} символу","count.line.html.one":"{n} картка на дошці просто зараз","count.line.html.other":"{n} картки на дошці просто зараз","people.humans.html.one":"👥 {n} людина","people.humans.html.other":"👥 {n} людей","people.agents.html.one":"🤖 {n} агент","people.agents.html.other":"🤖 {n} агентів","people.working.html.one":"⚡ {n} у роботі просто зараз","people.working.html.other":"⚡ {n} у роботі просто зараз","pre.title":"AI-gile: тут щось будується","pre.description":"Тут щось будується: дошка, на якій ШІ-команди будують те, що ти просиш, і навчають тебе дорогою. Поки що закрита пре-альфа з друзями.","pre.h1":"Тут щось будується. 🤫","pre.line":"Дошка, на якій ШІ-команди будують те, що ти просиш, і навчають тебе дорогою. Поки що закрита пре-альфа з друзями.","pre.btn":"🔔 Сповісти, коли відкриється","pre.peek":"За склом: справжня дошка, наживо. Кожна картка — кольорова смужка.","pre.peekFake":"За склом: так виглядає дошка в роботі.","features.aria":"Що він робить","f.pile.h":"Одна купка для тебе","f.pile.html":"<b>Для тебе</b> збирає все, що чекає на тебе в усіх проєктах: запитання, речі на перевірку, завдання, які може зробити лише людина. Твоя черга показує, що далі і скільки це займе.","f.sleep.h":"Команди, що працюють, поки ти спиш","f.sleep.p":"У кожного проєкту є лід і команда ШІ-агентів. Напиши коментар до картки, і команда прокинеться, зробить роботу й поверне її з кроками, які зрозуміє навіть невиспана людина.","f.tester.h":"Спершу перевіряє ШІ-тестувальник","f.tester.p":"Перш ніж щось дійде до тебе, тестувальник проходить кроки в копії застосунку й показує, що побачив, зі скриншотом. Перегляни ті, що пройшли, і прийми одним клацанням.","f.proof.h":"Докази, а не обіцянки","f.proof.p":"Кожна передача показує, що змінилося: файли, різницю, скриншоти. Не треба відкривати кожен застосунок, щоб дізнатися, чи все готово.","f.chat.h":"Спілкуйся зі своїми лідами","f.chat.p":"Бічна панель у стилі Discord: по значку на проєкт, фіолетові діаманти там, де потрібен ти. Напиши ліду ідею, і він перетворить її на картки та план з кнопкою ✅ Почати.","f.tidy.h":"Сам тримає лад","f.tidy.p":"Схожі картки зливаються в одну, заплутані назви виправляються, а перевірка токенів тримає код легким. Менше перемикань і менше думок.","f.private.h":"Твоє, на твоєму комп'ютері","f.private.li1":"Дошка працює на твоїй машині й відповідає лише тобі.","f.private.li2":"Приватні повідомлення між людьми наскрізно зашифровані.","f.private.li3":"Жодних акаунтів, трекерів і кукі.","f.lang.h":"Твоєю мовою","f.lang.p":"Понад 120 мов: від нідерландської, валлійської та японської до піратської, мови Йоди й клінгонської, зі швидким поверненням до англійської для фахових термінів.","f.service.h":"Від ідеї до справжнього сервісу","f.service.p":"Створив щось із ШІ, і цим уже користуються люди? Познач це як сервіс, і дошка допоможе добре його вести: перевірки доступності, публічна сторінка статусу, інциденти з розбором, зміни, яким потрібне Go, резервні копії, які перевіряють щодня. Довідка пояснює кожен крок, коли ти до нього доходиш.","msgr.h2":"AI-gile Messenger: твоя команда в кишені","msgr.p1":"Спілкуйся зі своєю AI-командою, не відкриваючи дошку. Пиши лідам своїх проєктів і друзям, переглядай кроки тестування картки й відповідай на них, усе з телефона.","msgr.p2":"Щоб під'єднати, відскануй QR-код на своїй дошці. Уперше? Привітний демо-чат усе покаже.","msgr.when":"Спершу Android, потім вебверсія для телефонів та iPhone.","msgr.who":"Лід твого проєкту","msgr.b1":"Виправлення темної теми готове. Надіслати кроки тестування?","msgr.b2":"Так, будь ласка!","msgr.b3":"1. Відкрий Налаштування. 2. Вибери Темна. Усе виглядає як слід?","tl.aria":"Часова шкала від першої розмови до дорожньої карти","tl.h2":"Від першої розмови до того, що далі","tl.lede":"Справжні дати й час, у твоєму часовому поясі. Після сьогодні — це план, без обіцяних дат.","tl.today":"Сьогодні","tl.planned":"заплановано","tl.doing":"у роботі","tl.cards.one":"{n} картка","tl.cards.other":"{n} картки","join.h2":"Долучайся","join.lede":"AI-gile будують бородатий дивак з AuDHD і кількома битвами за психічне здоров’я — і дуже багато терплячих агентів. Поки що він приватний, у закритій альфі з друзями. Хочеш спробувати, коли він відкриється?","join.btn":"Записати свій інтерес","join.small":"Ми напишемо тобі листа, і більше нічого","footer.tag":"AI-gile. Без трекерів, без кукі, без кави на стендапі.","footer.licence":"Бізнес-ліцензія","footer.status":"Статус","footer.privacy":"Що ми зберігаємо","footer.thanks":"Дзвінки завдяки ChilledChat","form.sending":"Надсилаємо…","form.failed":"Не вийшло: спробуй пізніше.","form.offline":"Не вдалося зв'язатися з AI-gile: спробуй пізніше.","form.keep":"Ми використовуємо це лише для відповіді тобі, а потім видаляємо. Жодних трекерів, жодних кукі.","form.keepLink":"Що ми зберігаємо","interest.title":"AI-gile: скажіть мені, коли відкриється альфа","interest.description":"Залиш свою пошту, щоб дізнатися, коли відкриється закрита альфа чи бета AI-gile.","interest.h1":"🔔 Сповісти, коли відкриється","interest.lede":"AI-gile у закритій пре-альфі. Залиш пошту, і ми напишемо один раз, коли для тебе знайдеться місце.","interest.email":"Твоя пошта","interest.which":"Яке тестування?","interest.alpha":"Закрита альфа: рання, сира, багато змін","interest.beta":"Бета: стабільніша, пізніше","interest.both":"Будь-яке, що з'явиться першим","interest.submit":"Додайте мене до списку","interest.thanks":"Дякуємо! Ти в списку.","licence.title":"AI-gile: бізнес-ліцензія","licence.description":"Користуєшся AI-gile у своїй справі? Подай заявку на безкоштовну бізнес-ліцензію.","licence.h1":"📜 Бізнес-ліцензія","licence.lede":"Користуєшся AI-gile на роботі? Розкажи, хто ти й чим займаєшся. Якщо це приносить трохи добра, ліцензія безкоштовна.","licence.company":"Компанія","licence.website":"Вебсайт","licence.what":"Чим ти займаєшся","licence.how":"Чим це допомагає світові","licence.email":"Пошта","licence.submit":"Подати заявку","licence.thanks":"Дякуємо! Ми відповімо на пошту.","status.title":"Статус AI-gile","status.h1":"Статус AI-gile","status.quiet":"Усе тихо","status.intro":"Чи працює AI-gile просто зараз? Ця сторінка кожні 5 хвилин перевіряє сайт, спільний доступ до дошок, дзвінки та завантаження.","status.up":"Працює (відповів за {ms} мс)","status.slow":"Не відповів на останню перевірку, пробуємо ще","status.down":"Не працює: не відповів на дві останні перевірки","status.svc.web":"Сайт","status.svc.web.offers":"Цей сайт: що таке AI-gile, і форма «Сповісти, коли відкриється»","status.svc.boards":"Спільний доступ до дошок","status.svc.boards.offers":"Публічні дошки, повідомлення між друзями та запрошення","status.svc.calls":"Дзвінки","status.svc.calls.offers":"Голос, відео й демонстрація екрана в AI-gile","status.svc.download":"Завантаження","status.svc.download.offers":"Інсталятор для Windows і посилання-запрошення","status.checking":"Перевіряємо…","status.offline":"Зараз не вдається зв'язатися зі службою статусу (пробуємо ще)","status.updated":"оновлено {ago}","status.justNow":"щойно","status.min":"{n} хв тому","status.hours":"{n} год тому","status.days":"{n} дн. тому","privacy.title":"AI-gile: що ми зберігаємо","privacy.h1":"Що ми зберігаємо","privacy.lede":"Коротко: лише те, що ти нам надсилаєш, і ненадовго.","privacy.only":"Лише те, що ти нам надсилаєш: те, що ти вводиш у форму, наприклад свою пошту. Більше нічого про тебе.","privacy.sealed":"Усе запечатується, тож наш сервер не може цього прочитати: у твоєму браузері ще до відправлення (у старішому браузері одразу після надходження). Відкрити це може лише наша власна дошка.","privacy.server":"Це видаляється із сервера, щойно потрапляє на нашу дошку. Усе, що залишилося там через 30 днів, однаково видаляється.","privacy.board":"Ми зберігаємо це на нашій дошці лише доти, доки не відповімо тобі, а потім видаляємо й там.","privacy.none":"Жодних трекерів, кукі чи аналітики.","privacy.local":"Твоя мова та вибір світлої чи темної теми залишаються у твоєму браузері. Нам їх ніколи не надсилають.","privacy.ask":"Хочеш, щоб це зникло раніше? Просто відповідай на наш лист і напиши про це.","live.h2":"Дивіться, як це будується, наживо","live.caption":"Кожна картка прихована: ви бачите форму роботи, а не слова.","live.watching.one":"наживо: дивиться {n}","live.watching.other":"наживо: дивляться {n}","live.last.now":"Останню картку переміщено щойно","live.last.min.one":"Останню картку переміщено {n} хв тому","live.last.min.other":"Останню картку переміщено {n} хв тому","live.last.hour.one":"Останню картку переміщено {n} год тому","live.last.hour.other":"Останню картку переміщено {n} год тому","live.last.day.one":"Останню картку переміщено {n} дн. тому","live.last.day.other":"Останню картку переміщено {n} дн. тому","live.offline":"Жива дошка трохи перепочиває. Заходьте знову згодом.","live.cols":"Беклог|До виконання|У роботі|Команда перевіряє|Тобі на тест|Для команди|Готово","pitch.words.few":"{n} слова","pitch.words.many":"{n} слів","pitch.letters.few":"{n} літери","pitch.letters.many":"{n} літер","pitch.chars.few":"{n} символи","pitch.chars.many":"{n} символів","count.line.html.few":"{n} картки на дошці просто зараз","count.line.html.many":"{n} карток на дошці просто зараз","tl.cards.few":"{n} картки","tl.cards.many":"{n} карток"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Канбан.","Роботи.","Делеговано."]},{"n":2,"texts":["Канбан роботів.","Агенти, впорядковані.","Ідеї збудовано."]},{"n":3,"texts":["Канбан для роботів.","Ідеї стають функціями.","Безкоштовний канбан агентів."]},{"n":5,"texts":["Канбан-дошка, яку ведуть агенти.","Ти пишеш картки. Агенти будують.","Безкоштовно, локально, перевірено, трохи безглуздо."]},{"n":8,"texts":["Безкоштовна канбан-дошка, де замість людей працюють ШІ-агенти.","Напиши ідею. Агенти збудують. Ти приймеш.","Agile для однієї людини й багатьох терплячих роботів."]},{"n":13,"texts":["Канбан-дошка на твоєму комп'ютері, де картки беруть у роботу ШІ-агенти.","Напиши ідею. Команда агентів її збудує, а тестувальник усе перевірить. Ти лише приймаєш.","Безкоштовно, без акаунтів і трекерів: дошка, трохи роботів і ти за головного."]},{"n":21,"texts":["AI-gile — це канбан-дошка для роботи з ШІ-агентами, що пишуть код. Вони беруть картки в роботу, а ти їх перевіряєш і приймаєш.","У кожного проєкту є лід і команда ШІ-агентів. Напиши коментар до будь-якої картки, і команда береться до роботи.","Безкоштовна особиста дошка завдань на твоєму власному комп'ютері. Працюють там роботи, а казати остаточне «так» будеш ти."]},{"n":34,"texts":["Ти кладеш ідеї на дошку. Команда ШІ-агентів перетворює їх на робочі функції, перевіряє й повертає тобі з кроками для спроби. Нічого не вважається готовим, доки ти цього не скажеш.","AI-gile — це саморобна канбан-дошка, яку Rich збудував із великою допомогою агентів, якими вона тепер керує. Вона безкоштовна, працює на твоєму комп'ютері й призначена для друзів, а не на продаж.","Уяви звичайну канбан-дошку з колонками від Беклогу до Готово, тільки картки тут беруть у роботу ШІ-агенти. Вони звітують про хід справи, питають, коли застрягли, і завжди чекають твого схвалення."]},{"n":55,"texts":["AI-gile — це канбан-дошка, де команда складається зі ШІ-агентів. У кожного проєкту є лід, який планує роботу, і помічники, які її виконують. Коли функція готова, ШІ-тестувальник пробує її й робить скриншот, а потім вона потрапляє до твоєї купки. Прийми її або напиши коментар, і вони переробять.","Усе почалося як спосіб однієї людини стежити за багатьма сеансами ШІ-кодування одночасно, а потім виросло в справжню дошку. Вона працює на твоїй машині, не вимагає акаунта й не має трекерів. Безкоштовна для друзів і всіх допитливих. Вона ще й недороблена, тож чекай шорсткостей і зрідка сюрпризів.","Ось чесна версія. Ідеї все одно маєш мати ти, і результати все одно маєш перевіряти ти. А AI-gile робить усе між цим: тримає картки впорядкованими, будить потрібного агента, коли ти коментуєш, показує, що саме змінилося, і збирає все це для тебе в одну коротку купку."]},{"n":89,"texts":["AI-gile — це безкоштовна канбан-дошка, яку ти запускаєш на власному комп'ютері. Замість людей у кожного проєкту є команда ШІ-агентів: лід, що перетворює твої ідеї на картки та план, і помічники, що беруть картки за пріоритетом. Коли щось збудовано, ШІ-тестувальник проходить кроки перевірки й показує тобі, що побачив. Потім усе чекає в одній купці з назвою «Для тебе». Ти приймаєш або коментуєш, і команда пробує ще раз. Без тебе нічого не потрапляє в «Готово».","Є кілька речей, яких ти можеш не чекати. Нічна варта поповнює колонку «До виконання», поки ти спиш, і вибирає картки, яким не потрібна твоя відповідь. Лічильник токенів показує, скільки агенти витратили сьогодні й цього тижня, а режим «Без токенів» велить їм зупинитися. Можна писати друзям, і приватні повідомлення наскрізно зашифровані. Дошка говорить приблизно 120 мовами, зокрема нідерландською, фламандською, піратською та клінгонською. Це не коштує ні копійки, і ніхто не намагається тобі це продати.","AI-gile — невеликий особистий проєкт, а не компанія. Rich хотів доглядати кілька проєктів зі ШІ-кодуванням, не відкриваючи щоразу кожен застосунок, тож разом з агентами збудував для цього дошку, а потім нею ж збудував решту себе. Вона в закритій пре-альфі, тобто здебільшого працює, але лише для жменьки друзів. Немає ні сторінки з цінами, ні розсилки, ні плану зростання. Якщо все це звучить корисно, можеш попроситися спробувати, щойно вона трохи відкриється для інших охочих."]},{"n":144,"texts":["AI-gile — це канбан-дошка для однієї людини й багатьох ШІ-агентів. Вона працює на твоєму власному комп'ютері й повністю безкоштовна. Ти додаєш проєкти, і кожен отримує ліда та невелику команду. Ти спілкуєшся з лідом, трохи як у Discord, і описуєш ідею; лід перетворює її на картки та план, а потім чекає, поки ти натиснеш «Почати». Команда проходить картки за пріоритетом, користуючись простим командним рядком, створеним для мовних моделей. Перш ніж щось повернеться до тебе, ШІ-тестувальник проходить усі кроки в копії застосунку й додає до них скриншот. Готова робота потрапляє до твоєї купки разом зі зміненими файлами та різницею. Ти приймаєш її або залишаєш коментар, і команда прокидається та пробує знову. Лише ти можеш перемістити картку в колонку «Готово».","День з AI-gile, приблизно. Увечері ти залишаєш кілька коментарів: ця кнопка не на місці, той список варто відсортувати, а чи можна додати темну тему. Ти йдеш спати. Агенти читають коментарі, вносять зміни, перевіряють їх і повертають тобі. Якщо «До виконання» порожніє, нічна варта наповнює його з беклогу картками, яким не потрібна твоя відповідь. Зранку на тебе чекає одна коротка купка: кілька запитань і кілька речей на спробу, кожна з кроками, які зрозуміє навіть сонна людина, і зі скриншотом, де все працює. Ти клацаєш, приймаєш добре, а решту відправляєш назад. Лічильник токенів показує, скільки це все з'їло, а режим «Без токенів» є для ощадливих тижнів. Потім ти снідаєш, і в цьому агенти поки що не допоможуть.","Спершу про те, чим AI-gile не є. Це не стартап, не товар на продаж, і ніхто не збирає твої дані. Це безкоштовна дошка, що працює на твоєму комп'ютері, без акаунтів, трекерів і кукі. А є вона єдиним охайним місцем, де видно всі проєкти зі ШІ-кодуванням одразу: команда агентів робить картки, а рішення ухвалюєш ти. Вона зливає схожі картки, виправляє заплутані назви й стежить, наскільки легким лишається код. Вона говорить приблизно 120 мовами, від нідерландської та фламандської до піратської й клінгонської. Друзі можуть писати одне одному приватно й зашифровано. Її збудували Rich і дуже багато терплячих агентів, здебільшого користуючись нею самою. Вона в закритій пре-альфі, тож подекуди шорстка. Якщо звучить цікаво, попроси чемно, і, можливо, потрапиш раніше."]}],"quips":{"1":"Одне слово. Сміливо. Можливо, занадто сміливо.","3":"Три слова. Вже чесніше за більшість сторінок продуктів.","8":"Вісім слів. Усе одно коротше за стендап.","21":"До речі, довжини — це story points. А що ж іще.","55":"П'ятдесят п'ять слів. Поки ти читав, дві картки встигли завершити.","144":"Це найдовший варіант. 233 немає. Агенти пішли спати."}},"timeline":{"first-idea.name":"Перша ідея","first-idea.line":"Найперша розмова, коли коду ще не існувало.","first-board.name":"Перша дошка","first-board.line":"Дошка, що стежить за власною розробкою: картки, колонки, перетягування, проєкти.","team-roles.name":"Команда й ролі","team-roles.line":"Профілі агентів, шаблони команд, простори й хто що робить.","install.name":"Встановлення й релізи","install.line":"Zip, який друг може встановити, самооновлення, канали й відкат.","usage-saver.name":"Заощадження ресурсу","usage-saver.line":"Міряти вартість запусків, тримати код легким, берегти свій ліміт.","friends.name":"Друзі й спільний доступ","friends.line":"Приватні повідомлення, зашифрований ретранслятор, запрошення, ролі й спільні проєкти.","languages.name":"Мови","languages.line":"Кожен екранний текст у мовному файлі, спершу нідерландська й фламандська.","ai-tester.name":"ШІ-тестувальник","ai-tester.line":"Тестувальник першим перевіряє кожну передачу й показує, що побачив.","website.name":"Вебсайт","website.line":"aigile.lol, тизер і ця часова шкала.","streaming.name":"Чат і стримінг","streaming.line":"Discord, Twitch, OBS, режим стримера, GIF-и й емодзі.","no-ai.name":"Версія без ШІ","no-ai.line":"Дошка для тих, хто пише код без ШІ, і публічні дошки.","night-watch.name":"Нічна варта","night-watch.line":"Вартовий і Scrum Master тримають команди в роботі, поки ти спиш.","p-more.name":"Усе інше","p-more.line":"Менші ідеї, що чекають своєї черги.","p-android.name":"Телефон і Android","p-android.line":"Доступ до дошки з телефона, а потім рідний застосунок для Android.","p-release.name":"Альфа й далі","p-release.line":"Закрита альфа, жива сторінка, потім бета.","p-languages.name":"Більше мов","p-languages.line":"Понад сотня мов і режим занурення для тих, хто вчить мову.","p-engines.name":"Більше ШІ-рушіїв","p-engines.line":"Обирай Claude, Codex або Gemini для кожного агента.","p-pro.name":"Професійна практика","p-pro.line":"Мітки ризику, ворота злиття, картки інцидентів і запобіжники.","p-self.name":"Турбота про тебе","p-self.line":"Режим втоми, нагадування про догляд за собою і 4:20.","p-servers.name":"Сервери й масштаб","p-servers.line":"Глобальні налаштування сервера, ролі й планування зростання.","p-livestream.name":"Додатки для стримінгу","p-livestream.line":"Чат Twitch, власні емодзі й публічний перегляд наживо."},"words":{"button":"📖 Фахові терміни","h":"📖 Слова простими словами","intro":"Слова, які трапляються в AI-gile, простою мовою: як щось створити, як безпечно змінювати, як підтримувати його роботу для людей, які ним користуються, і як працювати командою разом із ШІ.","search":"Шукати слово…","none":"Такого слова немає.","close":"Закрити","count":{"one":"{count} слово","other":"{count} слів"},"groups":[{"id":"build","name":"🛠️ Створення"},{"id":"change","name":"🔀 Безпечні зміни"},{"id":"run","name":"🛎️ Робота сервісу"},{"id":"team","name":"🤝 Робота командою (і з ШІ)"}],"list":[{"id":"repo","g":"build","word":"Репозиторій","text":"Папка проєкту з кодом і повною історією комітів, зазвичай також збережена на GitHub.","also":["репо","repo","repository"]},{"id":"branch","g":"build","word":"Гілка","text":"Окрема лінія роботи в коді, щоб можна було вносити зміни, не чіпаючи основну версію.","also":["гілки","branch","branches"]},{"id":"commit","g":"build","word":"Коміт","text":"Збережений знімок коду з короткою приміткою про те, що змінилося. До нього завжди можна повернутися.","also":["коміти","комітів","commit","commits"]},{"id":"push","g":"build","word":"Пуш","text":"Надсилання збережених знімків (комітів) з цього комп'ютера на GitHub, щоб вони були збережені й доступні іншим."},{"id":"merge","g":"build","word":"Мерж","text":"Злиття змін гілки назад в основну версію."},{"id":"pr","g":"build","word":"Пул-реквест","text":"Прохання перевірити зміни гілки й злити їх в основну версію.","also":["PR","pull request"]},{"id":"refactor","g":"build","word":"Рефакторинг","text":"Наведення ладу в коді без зміни того, що він робить: менші файли, зрозуміліші назви, менше повторів."},{"id":"bug","g":"build","word":"Баг","text":"Щось, що не працює так, як має.","also":["баги","бага","багів","bug","bugs"]},{"id":"test","g":"build","word":"Тест","text":"Перевірка готової роботи, щоб переконатися, що вона робить те, що просили, перш ніж ти її приймеш.","also":["тести","тесту","тестів","тестування","тестувати","test","tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Скорочення від quality assurance, тобто контроль якості: автоматичні перевірки, які запускаються, перш ніж щось вийде у світ. Якщо QA червоний, щось не пройшло, і поки це не виправлять, нічого не вийде.","also":["контроль якості","перевірки якості","quality assurance","quality checks"]},{"id":"deploy","g":"change","word":"Деплой","text":"Розгортання нової версії, наприклад на сервері, де нею користуються люди."},{"id":"release","g":"change","word":"Реліз","text":"Набір готової роботи з назвою, який виходить у світ разом, із короткими нотатками про те, що змінилося. 🚀 Релізи пише ці нотатки з готових карток.","also":["релізи","релізу","релізів","release","releases"]},{"id":"rollback","g":"change","word":"Відкат","text":"Повернення до останньої версії, яка працювала, коли нова створює проблеми. В AI-gile з'являється чекліст кроків скасування, записаних у кожній зміні.","also":["відкату","відкотити","відкочено","rollback","roll back","roll-back","rolled back"]},{"id":"live","g":"change","word":"Продакшн","text":"Справжня версія, якою користуються люди, на відміну від копії, щоб щось спробувати. Коли щось туди потрапляє, кажуть, що воно виходить у світ. Розробники називають це продакшн або просто прод.","also":["прод","робоча версія","наживо","live","production"],"noTip":1},{"id":"change","g":"change","word":"Зміна","text":"Запланована зміна в чомусь, на що покладаються люди, спершу записана: що, навіщо, який ризик, коли і як її скасувати. Почни з 🔀 Створити запит на зміну.","also":["зміни","змін","запит на зміну","запити на зміну","change","change request"],"noTip":1},{"id":"risk","g":"change","word":"Ризик","text":"Те, що може піти не так, з оцінкою, наскільки це ймовірно і наскільки погано. ⚠️ Ризики тримає їх в одному списку, найвища оцінка зверху, і в кожного є дата, коли переглянути знову.","also":["ризики","ризиків","реєстр ризиків","risk","risks","risk register"]},{"id":"chgwin","g":"change","word":"Вікно змін","text":"Час, коли зміни можна випускати у світ, наприклад спокійний вівторковий вечір. Поза вікном картку зміни не можна завершити, хіба що це термінова ситуація.","also":["вікна змін","change window","change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Швидке голосування просто перед тим, як зміна вийде у світ: кожен, хто має погодити, каже Go або No go. Зміна йде далі, лише коли всі згодні.","also":["go/no go","go-no-go","так чи ні"]},{"id":"approval","g":"change","word":"Погодження","text":"Очікування «так» перед початком роботи. Картка, яку створив друг, або зміна чекає в ✅ Погодження, доки ти її не погодиш чи не відхилиш.","also":["погодити","схвалення","approval","approvals"]},{"id":"quiettime","g":"change","word":"Тихі години","text":"Проміжок часу, наприклад стрим, демо чи ніч, коли нічого не виходить у світ. Команди далі працюють і тестують, але вихід чекає, доки він не скінчиться. Ще це називають заморожуванням змін.","also":["тихий час","заморожування змін","quiet time","quiet times","change freeze"]},{"id":"service","g":"run","word":"Сервіс","text":"Щось, що ти створив і на що покладаються люди, як-от сайт чи застосунок, і за чим доглядають, щоб воно працювало. Постав позначку «Цей проєкт — сервіс» і вкажи, що він пропонує, хто ним користується і хто чергує.","also":["сервіси","сервісу","сервісів","service","services"]},{"id":"uptime","g":"run","word":"Перевірка доступності","text":"Автоматична перевірка кожні кілька хвилин, що твій сервіс досі відповідає. Якщо вона не проходить кілька разів поспіль, AI-gile сам відкриває картку інциденту.","also":["доступність","аптайм","перевірки доступності","uptime","uptime check","uptime checks"]},{"id":"statuspage","g":"run","word":"Сторінка статусу","text":"Публічна сторінка, яка показує, чи працює сервіс (зелений, помаранчевий чи червоний), з останнім оновленням, щоб люди, які ним користуються, могли перевірити самі, а не питати.","also":["сторінки статусу","статус-сторінка","status page","status pages"]},{"id":"desk","g":"run","word":"Service desk","text":"Where questions and reports from the people using your service come in. AI-gile sorts each one into a request, an incident or an idea, and says so when it looks like something already reported.","also":["service desks","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Service request","text":"Someone asking for something ordinary, like a new account or a bit of help, rather than reporting that something is broken. It waits its turn; an incident goes first.","also":["service requests"]},{"id":"incident","g":"run","word":"Інцидент","text":"Щось, що зламалося для людей, які користуються цим просто зараз, наприклад сайт не працює. Картка 🔥 інциденту йде поза чергою: спершу треба, щоб усе знову запрацювало.","also":["інциденти","інциденту","інцидентів","incident","incidents"]},{"id":"major","g":"run","word":"Великий інцидент","text":"Великий інцидент: зачеплено багато людей або під загрозою гроші чи дані. Одна кнопка кидає на нього всі команди (рій), будить того, хто чергує, і просить оновлення статусу кожні 30 хвилин.","also":["великі інциденти","серйозний інцидент","major incident","major incidents"]},{"id":"oncall","g":"run","word":"Чергування","text":"Бути тим, хто відповідає, коли щось ламається, навіть уночі. У кожного сервісу є черговий учасник команди, якого будять першим через його інциденти.","also":["черговий","чергова зміна","на чергуванні","on call","on-call"]},{"id":"replyby","g":"run","word":"Час відповіді","text":"Скільки картка може чекати на першу відповідь, наприклад годину для інциденту. Після цього на ній з'являється червоний годинник, щоб ніщо тихо не забулося. Ще це називають цільовим часом відповіді.","also":["термін відповіді","цільовий час відповіді","reply-by time","response target","response targets"]},{"id":"postmortem","g":"run","word":"Розбір інциденту","text":"Короткий погляд назад після інциденту: що сталося, що допомогло і що змінити, без пошуку винних. Без нього інцидент не можна закрити. Ще кажуть «постмортем».","also":["розбори інцидентів","постмортем","post-mortem","post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Проблема","text":"Прихована причина одного чи кількох інцидентів. Картка 🧩 проблеми збирає інциденти, які повертаються знову і знову, щоб причину знайшли і виправили назавжди.","also":["проблеми","проблем","problem","problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Першопричина","text":"Справжня причина, чому щось зламалося, а не лише те, що ти бачив. Виправ першопричину, і інцидент перестане повертатися.","also":["першопричини","коренева причина","root cause","root causes"]},{"id":"workaround","g":"run","word":"Обхідний шлях","text":"Спосіб, щоб усе працювало, поки справжнє виправлення не готове, наприклад перезапустити щось, коли воно зависає. Його записують у картці проблеми, щоб нікому не довелося вигадувати його знову.","also":["обхідні шляхи","тимчасове рішення","воркераунд","workaround","workarounds"]},{"id":"knownerror","g":"run","word":"Відома помилка","text":"Проблема, причину якої зрозуміли і для якої є обхідний шлях, але яку ще не виправили. 🧩 Відомі помилки збирає їх у список, щоб усі користувалися обхідним шляхом, а не шукали знову.","also":["відомі помилки","відомих помилок","known error","known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Покрокова інструкція, як виправити відомий вид проблеми, щоб це робили однаково і швидко щоразу. Після великого інциденту команда може запропонувати runbook, а ти його схвалиш.","also":["runbooks","ранбук","інструкція","покрокова інструкція"]},{"id":"ci","g":"run","word":"Configuration item","text":"One thing your service depends on, like a server, a domain, a certificate, a key or a supplier. 🗂️ Configuration items lists them per service, so you can see what an incident affects and what needs renewing or a backup.","also":["configuration items"]},{"id":"expiry","g":"run","word":"Expiry date","text":"AI-gile keeps an eye on dates like when a certificate or a domain runs out. Within 30 days of the date it makes one card to renew it, so nothing stops working by surprise.","also":["expiry dates","expiry","expiry watch"]},{"id":"backup","g":"run","word":"Резервна копія","text":"Збережена раніше копія твоїх даних, на яку можна спертися, якщо щось загубилося чи пошкодилося. AI-gile щодня робить резервну копію твоїх дошок.","also":["резервні копії","бекап","бекапи","backup","backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Відновлення","text":"Повернення даних із резервної копії. Резервна копія насправді чогось варта, лише коли ти знаєш, що її можна відновити, тож варто час від часу пробувати.","also":["відновити","відновлено","restore","restored"]},{"id":"svcreview","g":"run","word":"Service review","text":"A look back at one month of a service: incidents opened and fixed, how quickly people got an answer, uptime and tokens used. The Monthly review shows it for each service.","also":["service reviews","monthly review","monthly reviews"]},{"id":"accessreview","g":"run","word":"Access review","text":"Checking every 90 days who can still get in: share links, friends’ roles and kept secrets. You keep or remove each one, so old access doesn’t linger.","also":["access reviews"]},{"id":"improvements","g":"run","word":"Improvement list","text":"Everything the team decided to get better at, in one place: retro suggestions, review actions and problem fixes, each with its status. Find it under 📈 Improvements.","also":["improvement lists","improvements"]},{"id":"tokencap","g":"run","word":"Token cap","text":"A monthly limit on the tokens a service’s agents may use. At 80% you get a warning; at 100% their background work waits until next month or until you raise the cap.","also":["token caps"]},{"id":"backlog","g":"team","word":"Беклог","text":"Ідеї й робота, яку ще не заплановано. Над ними ніхто не працює, доки картка не перейде в «До виконання»."},{"id":"sprint","g":"team","word":"Спринт","text":"Короткий відрізок роботи (часто тиждень-два) із чітко узгодженим набором карток, які треба закінчити.","also":["спринти","спринтів","спринту","sprint","sprints"]},{"id":"standup","g":"team","word":"Стендап","text":"Швидка зустріч: що зробив кожен учасник команди, що робить далі і що йому заважає.","also":["стендапи","стендапу","standup","stand-up","stand-ups"]},{"id":"kanban","g":"team","word":"Канбан","text":"Дошка зі стовпцями (До виконання, У роботі, Готово), де картки рухаються зліва направо в міру роботи."},{"id":"wip","g":"team","word":"WIP-ліміт","text":"Work in progress: максимум карток, які має вміщати стовпець, щоб команда закінчувала справи, перш ніж братися за нові.","also":["WIP","ліміт WIP"]},{"id":"dod","g":"team","word":"Визначення «Зроблено»","text":"Короткий чекліст команди про те, що означає «готово», наприклад перевірено й пояснено, перш ніж картку передадуть тобі. Його близнюк, визначення «Готово до роботи», каже, коли картка достатньо зрозуміла, щоб почати.","also":["Definition of Done","Definition of Ready","визначення «Готово до роботи»","DoD","DoR"]},{"id":"testpile","g":"team","word":"Купка тестів","text":"Готові картки, які чекають, поки ти їх спробуєш, одна за одною. Прийми картку або поверни її з приміткою, і з'явиться наступна.","also":["купки тестів","test pile","test piles"]},{"id":"retro","g":"team","word":"Ретро","text":"Погляд назад на те, як працює команда, щоб домовитися про одну річ, яку робити краще. В AI-gile ретро пропонує зміну в способах роботи команди, а ти кажеш Go або Ще ні.","also":["ретроспектива","ретроспективи","retro","retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Перевірка колегами","text":"Друга пара очей: інший ШІ перевіряє роботу кожної картки, перш ніж вона дійде до тебе, тож менше помилок проскакує.","also":["рев'ю","код-рев'ю","peer review","code review"]},{"id":"swarm","g":"team","word":"Рій","text":"Усі на палубу: кожна команда кидає іншу роботу, щоб допомогти з одним терміновим проєктом, доки його не розберуть. Інші проєкти тим часом чекають.","also":["роєм","усі на палубу","swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Той, хто стежить, щоб робота не стояла: помічає застряглі картки, підганяє команди і нагадує тобі, що чекає. В AI-gile це робить Lead Scrum Master у кожному проєкті.","also":["Lead Scrum Master","скрам-майстер"]},{"id":"agent","g":"team","word":"Агент","text":"ШІ, що самостійно працює над завданням: читає код, вносить зміни, запускає перевірки і звітує.","also":["агенти","агентів","agent","agents"]},{"id":"token","g":"team","word":"Токен","text":"Одиниця, у якій рахується використання ШІ: приблизно кілька літер тексту, прочитаних або написаних. Менше токенів - більше тарифу лишається.","also":["токени","токенів","token","tokens"]},{"id":"hook","g":"team","word":"Хук","text":"Маленька команда, яка сама запускається в певний момент, напр. коли стартує сесія ШІ, щоб команда чула твої коментарі.","also":["хуки","hook","hooks"]}]}};
